  "version": "1.0.0",
  "artifact_url": "https://developer.example/releases/connector-1.0.0.zip",
  "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
  "size_bytes": 12345,
  "platforms": [
    "windows-x64"
  ],
  "changelog": "Prima versiune a conectorului.",
  "signature_url": null
})
});
const result = await response.json();
if (!response.ok) throw new Error(result.message || result.error_description || ('HTTP ' + response.status));
console.log(result);
```

